import {clampIndex,includeFocused,type Activity} from "./activity";
export function VirtualActivityList({items,dynamic=false,onSelect,onRangeEnd}:{items:readonly Activity[];dynamic?:boolean;onSelect?:(id:number)=>void;onRangeEnd?:(index:number)=>void}){
 const parent=useRef<HTMLDivElement>(null),nodes=useRef(new Map<number,HTMLButtonElement>()),pendingFocus=useRef<number|null>(null);const [focusedId,setFocusedId]=useState<number|null>(null);const indexById=useMemo(()=>new Map(items.map((item,index)=>[item.id,index])),[items]);const getItemKey=useCallback((index:number)=>items[index].id,[items]);
 const rangeExtractor=useCallback((range:Parameters<typeof defaultRangeExtractor>[0])=>includeFocused(defaultRangeExtractor(range),focusedId===null?undefined:indexById.get(focusedId),items.length),[focusedId,indexById,items.length]);
 const virtualizer=useVirtualizer<HTMLDivElement,HTMLLIElement>({count:items.length,getScrollElement:()=>parent.current,estimateSize:()=>44,getItemKey,overscan:4,rangeExtractor});const rows=virtualizer.getVirtualItems();const offset=virtualizer.scrollOffset??0;const end=offset+(parent.current?.clientHeight??480);const lastVisible=rows.filter(row=>row.end>offset&&row.start<end).at(-1)?.index??-1;
 useEffect(()=>{onRangeEnd?.(lastVisible);},[lastVisible,onRangeEnd]);
 useEffect(()=>{if(focusedId!==null&&!indexById.has(focusedId)){setFocusedId(null);pendingFocus.current=null;}},[focusedId,indexById]);
 useLayoutEffect(()=>{const id=pendingFocus.current;if(id!==null){const node=nodes.current.get(id);if(node){node.focus({preventScroll:true});pendingFocus.current=null;}}});
 function move(index:number){const next=clampIndex(index,items.length);if(next<0)return;const id=items[next].id;pendingFocus.current=id;setFocusedId(id);virtualizer.scrollToIndex(next,{align:"auto"});}
 return <section><p>{items.length} zdarzeń. Strzałki, Home i End przenoszą fokus. Wyszukuj dane przez filtr aplikacji; Ctrl+F obejmuje tylko aktualny DOM.</p><div ref={parent} data-viewport="activity" role="region" aria-label="Aktywność" tabIndex={0} style={{height:480,overflow:"auto",border:"1px solid #999"}} onBlur={event=>{if(!event.currentTarget.contains(event.relatedTarget as Node|null))setFocusedId(null);}} onKeyDown={event=>{if(!["ArrowDown","ArrowUp","Home","End"].includes(event.key))return;event.preventDefault();const current=focusedId===null?rows.find(row=>row.end>offset)?.index??0:indexById.get(focusedId)??0;move(event.key==="Home"?0:event.key==="End"?items.length-1:current+(event.key==="ArrowDown"?1:-1));}}>
 <ul aria-label="Zdarzenia" style={{height:virtualizer.getTotalSize(),position:"relative",margin:0,padding:0,listStyle:"none"}}>{rows.map(row=>{const item=items[row.index];return <li key={row.key} data-index={row.index} aria-posinset={row.index+1} aria-setsize={items.length} ref={dynamic?virtualizer.measureElement:undefined} style={{position:"absolute",top:0,left:0,width:"100%",height:dynamic?undefined:row.size,transform:"translateY("+row.start+"px)",boxSizing:"border-box"}}><button ref={node=>{if(node)nodes.current.set(item.id,node);else nodes.current.delete(item.id);}} type="button" tabIndex={focusedId===item.id||focusedId===null&&row.index===0?0:-1} onFocus={()=>setFocusedId(item.id)} onClick={()=>onSelect?.(item.id)} style={{width:"100%",minHeight:44,height:dynamic?undefined:"100%",whiteSpace:dynamic?"normal":"nowrap",overflow:"hidden",textOverflow:"ellipsis",textAlign:"left"}} aria-label={"Wybierz zdarzenie "+item.id}>{item.text}</button></li>;})}</ul></div>{items.length===0&&<p role="status">Brak zdarzeń.</p>}</section>;
}

