import {act,fireEvent,render,screen,waitFor} from "@testing-library/react";import {afterEach,beforeEach,expect,test,vi} from "vitest";import {VirtualActivityList} from "./VirtualActivityList";import {InfiniteActivity} from "./InfiniteActivity";import {makeActivities,mergePages,readPage} from "./activity";
const heights=new Map<number,number>();const observers:newObserver[]=[];class newObserver{targets=new Set<Element>();constructor(private callback:ResizeObserverCallback){observers.push(this);}observe(target:Element){this.targets.add(target);}unobserve(target:Element){this.targets.delete(target);}disconnect(){this.targets.clear();}resize(){this.callback([...this.targets].map(target=>({target,borderBoxSize:[{blockSize:(target as HTMLElement).offsetHeight,inlineSize:600}]})) as unknown as ResizeObserverEntry[],this as unknown as ResizeObserver);}}
beforeEach(()=>{heights.clear();observers.length=0;vi.stubGlobal("ResizeObserver",newObserver);vi.spyOn(HTMLElement.prototype,"clientHeight","get").mockImplementation(function(this:HTMLElement){return this.dataset.viewport?480:0;});vi.spyOn(HTMLElement.prototype,"clientWidth","get").mockReturnValue(600);vi.spyOn(HTMLElement.prototype,"offsetHeight","get").mockImplementation(function(this:HTMLElement){return this.tagName==="LI"?heights.get(Number(this.dataset.index))??(Number(this.dataset.index)%3===0?88:44):480;});vi.spyOn(HTMLElement.prototype,"scrollHeight","get").mockImplementation(function(this:HTMLElement){return this.dataset.viewport?parseFloat((this.firstElementChild as HTMLElement)?.style.height??"0"):0;});Object.defineProperty(HTMLElement.prototype,"scrollTo",{configurable:true,value:function(this:HTMLElement,options:ScrollToOptions){this.scrollTop=options.top??0;this.dispatchEvent(new Event("scroll"));}});});afterEach(()=>{vi.unstubAllGlobals();vi.restoreAllMocks();});
test("10000 zdarzeń ma ograniczoną liczbę li",()=>{render(<VirtualActivityList items={makeActivities(10000)}/>);expect(screen.getAllByRole("listitem").length).toBeLessThan(30);expect(screen.getByRole("button",{name:"Wybierz zdarzenie 1"})).toBeInTheDocument();expect(screen.getAllByRole("listitem")[0]).toHaveAttribute("aria-setsize","10000");});
test("przewinięcie renderuje odpowiedni fragment zamiast całego zbioru",async()=>{render(<VirtualActivityList items={makeActivities(10000)}/>);const viewport=screen.getByRole("region",{name:"Aktywność"});fireEvent.scroll(viewport,{target:{scrollTop:4400}});await waitFor(()=>expect(screen.getByRole("button",{name:"Wybierz zdarzenie 101"})).toBeInTheDocument());expect(screen.queryByRole("button",{name:"Wybierz zdarzenie 1"})).not.toBeInTheDocument();expect(screen.getAllByRole("listitem").length).toBeLessThan(30);});
test("fokusowany wiersz pozostaje zamontowany poza widocznym oknem",async()=>{render(<VirtualActivityList items={makeActivities(10000)}/>);const first=screen.getByRole("button",{name:"Wybierz zdarzenie 1"});act(()=>first.focus());fireEvent.scroll(screen.getByRole("region"),{target:{scrollTop:4400}});await waitFor(()=>expect(screen.getByRole("button",{name:"Wybierz zdarzenie 101"})).toBeInTheDocument());expect(first).toBeInTheDocument();expect(first).toHaveFocus();expect(screen.getAllByRole("listitem").length).toBeLessThan(30);});
test("End i Home przewijają oraz przenoszą fokus do właściwego ID",async()=>{render(<VirtualActivityList items={makeActivities(10000)}/>);act(()=>screen.getByRole("button",{name:"Wybierz zdarzenie 1"}).focus());fireEvent.keyDown(document.activeElement!,{key:"End"});await waitFor(()=>expect(screen.getByRole("button",{name:"Wybierz zdarzenie 10000"})).toHaveFocus());fireEvent.keyDown(document.activeElement!,{key:"Home"});await waitFor(()=>expect(screen.getByRole("button",{name:"Wybierz zdarzenie 1"})).toHaveFocus());});
test("measureElement aktualizuje rozmiar po kontrolowanym ResizeObserver",async()=>{render(<VirtualActivityList items={makeActivities(10000)} dynamic/>);const list=screen.getByRole("list");act(()=>observers.forEach(observer=>observer.resize()));await waitFor(()=>expect(parseFloat(list.style.height)).toBeGreaterThan(440000));const before=parseFloat(list.style.height);heights.set(0,176);act(()=>observers.forEach(observer=>observer.resize()));await waitFor(()=>expect(parseFloat(list.style.height)).toBeGreaterThan(before));expect(screen.getAllByRole("listitem")[0]).toHaveAttribute("data-index","0");});
test("własny wybór odbiorcy otrzymuje ID zdarzenia",()=>{const select=vi.fn();render(<VirtualActivityList items={makeActivities(20)} onSelect={select}/>);fireEvent.click(screen.getByRole("button",{name:"Wybierz zdarzenie 2"}));expect(select).toHaveBeenCalledWith(2);});
test("doładowywanie nie uruchamia równoległych ani zapętlonych pustych stron",async()=>{let finish!:()=>void;const load=vi.fn(()=>new Promise<void>(resolve=>finish=resolve)),items=makeActivities(3);const view=render(<InfiniteActivity items={items} hasNextPage isFetching={false} error={false} loadNext={load}/>);await waitFor(()=>expect(load).toHaveBeenCalledTimes(1));view.rerender(<InfiniteActivity items={items} hasNextPage isFetching={false} error={false} loadNext={load}/>);expect(screen.getByRole("button",{name:"Wczytywanie…"})).toBeDisabled();await act(async()=>finish());expect(load).toHaveBeenCalledTimes(1);});
test("błąd doładowania pozwala na ręczne ponowienie",async()=>{const load=vi.fn().mockRejectedValueOnce(Error("offline")).mockResolvedValue(undefined);render(<InfiniteActivity items={makeActivities(2)} hasNextPage isFetching={false} error={false} loadNext={load}/>);expect(await screen.findByRole("alert")).toHaveTextContent("Nie doładowano");fireEvent.click(screen.getByRole("button",{name:"Doładuj zdarzenia"}));await waitFor(()=>expect(load).toHaveBeenCalledTimes(2));await waitFor(()=>expect(screen.queryByRole("alert")).not.toBeInTheDocument());});
test("koniec strumienia nie doładowuje",()=>{const load=vi.fn();render(<InfiniteActivity items={makeActivities(2)} hasNextPage={false} isFetching={false} error={false} loadNext={load}/>);expect(screen.getByRole("button",{name:"Koniec zdarzeń"})).toBeDisabled();expect(load).not.toHaveBeenCalled();});
test("fokus pozostaje przy domenowym ID po prependzie",()=>{const items=makeActivities(20);const view=render(<VirtualActivityList items={items}/>);const first=screen.getByRole("button",{name:"Wybierz zdarzenie 1"});act(()=>first.focus());view.rerender(<VirtualActivityList items={[{id:10001,text:"Nowe"},...items]}/>);expect(screen.getByRole("button",{name:"Wybierz zdarzenie 1"})).toBe(first);expect(first).toHaveFocus();});
test("kontrakt strony oraz merge po stabilnym ID",()=>{expect(()=>readPage({items:[{id:1,text:"A"},{id:1,text:"B"}],nextCursor:null})).toThrow();expect(()=>readPage({items:[],nextCursor:-1})).toThrow();expect(mergePages([{items:[{id:1,text:"A"}],nextCursor:1},{items:[{id:1,text:"B"},{id:2,text:"C"}],nextCursor:null}])).toEqual([{id:1,text:"A"},{id:2,text:"C"}]);});

